package com.brightloop.catalog;
import jakarta.validation.constraints.*;import java.math.BigDecimal;import java.time.Instant;
public final class CatalogDtos {private CatalogDtos(){}
 public record CustomerRequest(@NotBlank @Size(max=160) String fullName,@Email @NotBlank String email,@Size(max=40) String phone,@Size(max=160) String companyName,String billingAddress,String city,String state,String country,String postalCode,String taxId,@Pattern(regexp="ACTIVE|ARCHIVED") String status){}
 public record CustomerResponse(Long id,String fullName,String email,String phone,String companyName,String billingAddress,String city,String state,String country,String postalCode,String taxId,String status,Instant registeredAt){public static CustomerResponse of(Customer c){return new CustomerResponse(c.getId(),c.getFullName(),c.getEmail(),c.getPhone(),c.getCompanyName(),c.getBillingAddress(),c.getCity(),c.getState(),c.getCountry(),c.getPostalCode(),c.getTaxId(),c.getStatus(),c.getRegisteredAt());}}
 public record ProductRequest(@NotBlank @Size(max=160) String name,@NotBlank @Size(max=80) String productType,String description,@NotNull @DecimalMin("0.00") BigDecimal salesPrice,@DecimalMin("0.00") BigDecimal costPrice,String notes,@Pattern(regexp="ACTIVE|ARCHIVED") String status){}
 public record VariantRequest(@NotBlank @Size(max=120) String name,String attributeValue,@NotNull @DecimalMin("0.00") BigDecimal additionalPrice,@Pattern(regexp="ACTIVE|ARCHIVED") String status){}
 public record VariantResponse(Long id,String name,String attributeValue,BigDecimal additionalPrice,String status){public static VariantResponse of(ProductVariant v){return new VariantResponse(v.getId(),v.getName(),v.getAttributeValue(),v.getAdditionalPrice(),v.getStatus());}}
 public record ProductResponse(Long id,String name,String productType,String description,BigDecimal salesPrice,BigDecimal costPrice,String notes,String status,java.util.List<VariantResponse> variants){public static ProductResponse of(Product p,java.util.List<ProductVariant> vs){return new ProductResponse(p.getId(),p.getName(),p.getProductType(),p.getDescription(),p.getSalesPrice(),p.getCostPrice(),p.getNotes(),p.getStatus(),vs.stream().map(VariantResponse::of).toList());}}
}
